<?php

namespace mutation\translate\tests\unit;

use Craft;
use craft\db\Query;
use mutation\translate\models\SourceMessage;
use yii\db\IntegrityException;

/**
 * The `messageHash` column is generated by the database, and must match the hash computed in PHP.
 */
class MessageHashTest extends TestCase
{
    /**
     * @dataProvider messageProvider
     */
    public function testDatabaseHashMatchesPhp(string $message): void
    {
        $id = $this->insertRaw('site', $message);

        $hash = (new Query())->select(['messageHash'])->from('{{%source_message}}')->where(['id' => $id])->scalar();

        $this->assertSame(SourceMessage::hash($message), $hash);
        $this->assertSame($id, $this->plugin()->sourceMessage->getSourceMessageId('site', $message));
    }

    public static function messageProvider(): array
    {
        return [
            'ascii' => ['Hello'],
            'accents' => ['Café éàüç'],
            'emoji' => ['Party 🎉'],
            'japanese' => ['日本語のテキスト'],
            'typographic quotes' => ['“quotes” ‘single’ — …'],
            'line feed' => ["Line 1\nLine 2"],
            'crlf' => ["Line 1\r\nLine 2"],
            'tab' => ["Tab\there"],
            'trailing space' => ['trailing '],
            'leading space' => [' leading'],
            'empty' => [''],
            'zero' => ['0'],
            'quotes and backslash' => ['Quote \' " and \\ backslash'],
            'long (46 KB)' => [str_repeat('Long message éà 🎉 ', 2000)],
        ];
    }

    public function testRowsInsertedOutsideThePluginCantBeDuplicated(): void
    {
        $this->insertRaw('site', 'Raw');

        $this->assertNull($this->plugin()->messages->addMessage('Raw', 'site'));

        $this->expectException(IntegrityException::class);
        $this->insertRaw('site', 'Raw');
    }

    public function testNullValuesArentConstrained(): void
    {
        $this->insertRaw('site', null);
        $this->insertRaw('site', null);
        $this->insertRaw(null, 'No category');
        $this->insertRaw(null, 'No category');

        $this->assertSame(4, $this->countSourceMessages());
    }

    public function testHashFollowsMessageChanges(): void
    {
        $id = $this->insertRaw('site', 'Before');

        Craft::$app->getDb()->createCommand()->update('{{%source_message}}', ['message' => 'After'], ['id' => $id], [], false)->execute();
        $this->assertSame($id, $this->plugin()->sourceMessage->getSourceMessageId('site', 'After'));

        $sourceMessage = SourceMessage::findOne($id);
        $sourceMessage->message = 'After again';
        $this->assertTrue($sourceMessage->save());
        $this->assertSame($id, $this->plugin()->sourceMessage->getSourceMessageId('site', 'After again'));
        $this->assertNull($this->plugin()->sourceMessage->getSourceMessageId('site', 'After'));
    }

    public function testHashCantBeWritten(): void
    {
        $id = $this->insertRaw('site', 'Read only');

        $this->expectException(\yii\db\Exception::class);
        Craft::$app->getDb()->createCommand()->update('{{%source_message}}', ['messageHash' => md5('other')], ['id' => $id], [], false)->execute();
    }
}
